using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Xunit;

namespace MyApp.Evaluation;

/// <summary>
/// Evaluation harness that runs agentic chat scenarios and assesses response quality.
/// </summary>
public class EvaluationTests : IAsyncLifetime
{
    private DistributedApplication? _app;
    private IChatClient? _chatClient;

    public async Task InitializeAsync()
    {
        var builder = await DistributedApplicationTestingBuilder
            .CreateAsync<Projects.MyApp_AppHost>();

        _app = await builder.BuildAsync();
        await _app.StartAsync();

        _chatClient = _app.Services.GetRequiredService<IChatClient>();
    }

    public async Task DisposeAsync()
    {
        if (_app is not null)
        {
            await _app.StopAsync();
            await _app.DisposeAsync();
        }
    }

    [Fact]
    public async Task Greeting_ReturnsRelevantResponse()
    {
        Assert.NotNull(_chatClient);

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "Hello, how are you?")
        };

        var response = await _chatClient.GetResponseAsync(messages);
        var responseText = response.Text;

        Assert.NotNull(responseText);
        Assert.NotEmpty(responseText);
    }

    [Fact]
    public async Task FactualQuestion_ReturnsAccurateResponse()
    {
        Assert.NotNull(_chatClient);

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "What is the capital of France?")
        };

        var response = await _chatClient.GetResponseAsync(messages);
        var responseText = response.Text;

        Assert.NotNull(responseText);
        Assert.Contains("Paris", responseText, StringComparison.OrdinalIgnoreCase);
    }

    [Fact]
    public async Task MultiTurn_MaintainsContext()
    {
        Assert.NotNull(_chatClient);

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "My name is Alice."),
        };

        var firstResponse = await _chatClient.GetResponseAsync(messages);
        messages.Add(new ChatMessage(ChatRole.Assistant, firstResponse.Text));
        messages.Add(new ChatMessage(ChatRole.User, "What is my name?"));

        var secondResponse = await _chatClient.GetResponseAsync(messages);
        var responseText = secondResponse.Text;

        Assert.NotNull(responseText);
        Assert.Contains("Alice", responseText, StringComparison.OrdinalIgnoreCase);
    }
}

using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;

namespace MyApp.Evaluation;

/// <summary>
/// Loads scenarios from evaluation.yml and runs them against the chat client,
/// producing evaluation reports with quality metrics.
/// </summary>
public static class ScenarioRunner
{
    public static async Task<List<ScenarioResult>> RunScenariosAsync(
        IChatClient chatClient,
        IChatClient judgeChatClient,
        IEnumerable<EvaluationScenario> scenarios)
    {
        var results = new List<ScenarioResult>();

        foreach (var scenario in scenarios)
        {
            var messages = new List<ChatMessage>();
            ChatResponse? lastResponse = null;

            foreach (var turn in scenario.Turns)
            {
                messages.Add(new ChatMessage(ChatRole.User, turn.Content));
                lastResponse = await chatClient.GetResponseAsync(messages);
                messages.Add(new ChatMessage(ChatRole.Assistant, lastResponse.Text));
            }

            var evaluators = CreateEvaluators(judgeChatClient, scenario.Criteria);
            var evaluationResults = new List<EvaluationMetricResult>();

            foreach (var evaluator in evaluators)
            {
                var result = await evaluator.EvaluateAsync(messages, lastResponse!);
                evaluationResults.Add(result);
            }

            results.Add(new ScenarioResult(scenario.Name, evaluationResults));
        }

        return results;
    }

    private static List<IEvaluator> CreateEvaluators(
        IChatClient judgeChatClient,
        IEnumerable<EvaluationCriterion> criteria)
    {
        var evaluators = new List<IEvaluator>();

        foreach (var criterion in criteria)
        {
            IEvaluator evaluator = criterion.Metric.ToLowerInvariant() switch
            {
                "relevance" => new RelevanceEvaluator(judgeChatClient),
                "coherence" => new CoherenceEvaluator(judgeChatClient),
                "groundedness" => new GroundednessEvaluator(judgeChatClient),
                _ => throw new InvalidOperationException(
                    $"Unknown metric: {criterion.Metric}")
            };

            evaluators.Add(evaluator);
        }

        return evaluators;
    }
}

public interface IEvaluator
{
    Task<EvaluationMetricResult> EvaluateAsync(
        IList<ChatMessage> messages,
        ChatResponse response);
}

public record EvaluationScenario(
    string Name,
    string Description,
    List<ScenarioTurn> Turns,
    List<EvaluationCriterion> Criteria);

public record ScenarioTurn(string Role, string Content);

public record EvaluationCriterion(string Metric, int Threshold);

public record EvaluationMetricResult(string Metric, int Score, bool Passed);

public record ScenarioResult(string Name, List<EvaluationMetricResult> Metrics);

