namespace MyApp.Evaluation;

/// <summary>
/// Loads scenarios from evaluation.yml and runs them against the chat client,
/// producing evaluation reports with quality metrics.
/// </summary>
public static class ScenarioRunner
{
    public static async Task<List<ScenarioResult>> RunScenariosAsync(
        IChatClient chatClient,
        ChatConfiguration chatConfiguration,
        IEnumerable<EvaluationScenario> scenarios)
    {
        var results = new List<ScenarioResult>();

        foreach (var scenario in scenarios)
        {
            var messages = new List<ChatMessage>();
            ChatResponse? lastResponse = null;

            foreach (var turn in scenario.Turns)
            {
                messages.Add(new ChatMessage(ChatRole.User, turn.Content));
                lastResponse = await chatClient.GetResponseAsync(messages);
                messages.Add(new ChatMessage(ChatRole.Assistant, lastResponse.Text));
            }

            var evaluators = CreateEvaluators(scenario.Criteria);
            var evaluationResults = new List<EvaluationMetricResult>();

            foreach (var evaluator in evaluators)
            {
                var result = await evaluator.EvaluateAsync(
                    messages, lastResponse!, chatConfiguration);
                evaluationResults.AddRange(
                    result.Metrics.Select(m => new EvaluationMetricResult(
                        m.Key,
                        m.Value is NumericMetric nm ? (int)nm.Value.GetValueOrDefault() : 0,
                        m.Value is NumericMetric nm2 && nm2.Value.GetValueOrDefault() >= GetThreshold(scenario.Criteria, m.Key))));
            }

            results.Add(new ScenarioResult(scenario.Name, evaluationResults));
        }

        return results;
    }

    private static int GetThreshold(IEnumerable<EvaluationCriterion> criteria, string metric)
    {
        return criteria
            .FirstOrDefault(c => c.Metric.Equals(metric, StringComparison.OrdinalIgnoreCase))
            ?.Threshold ?? 3;
    }

    private static List<IEvaluator> CreateEvaluators(
        IEnumerable<EvaluationCriterion> criteria)
    {
        var evaluators = new List<IEvaluator>();

        foreach (var criterion in criteria)
        {
            IEvaluator evaluator = criterion.Metric.ToLowerInvariant() switch
            {
                "relevance" => new RelevanceEvaluator(),
                "coherence" => new CoherenceEvaluator(),
                "groundedness" => new GroundednessEvaluator(),
                _ => throw new InvalidOperationException(
                    $"Unknown metric: {criterion.Metric}")
            };

            evaluators.Add(evaluator);
        }

        return evaluators;
    }
}

