    string Name,
    string Description,
    List<ScenarioTurn> Turns,
    List<EvaluationCriterion> Criteria);

public record ScenarioTurn(string Role, string Content);

public record EvaluationCriterion(string Metric, int Threshold);

public record EvaluationMetricResult(string Metric, int Score, bool Passed);

public record ScenarioResult(string Name, List<EvaluationMetricResult> Metrics);

