using Aspire.Hosting;
using Aspire.Hosting.Testing;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using Xunit;

namespace MyApp.Evaluation;

/// <summary>
/// Evaluation harness that runs agentic chat scenarios and assesses response quality.
/// Uses Aspire testing infrastructure to spin up the AppHost and resolve the chat client.
/// </summary>
public class EvaluationTests : IAsyncLifetime
{
    private DistributedApplication? _app;
    private IChatClient? _chatClient;

    public async Task InitializeAsync()
    {
        var builder = await DistributedApplicationTestingBuilder
            .CreateAsync<Projects.MyApp_AppHost>();

        _app = await builder.BuildAsync();
        await _app.StartAsync();

        // Resolve the chat client from the app's service provider
        _chatClient = _app.Services.GetService<IChatClient>();
    }

    public async Task DisposeAsync()
    {
        if (_app is not null)
        {
            await _app.StopAsync();
            await _app.DisposeAsync();
        }
    }

    [Fact]
    public async Task Greeting_ReturnsRelevantResponse()
    {
        Assert.NotNull(_chatClient);

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "Hello, how are you?")
        };

        var response = await _chatClient.GetResponseAsync(messages);

        Assert.NotNull(response.Text);
        Assert.NotEmpty(response.Text);
    }

    [Fact]
    public async Task FactualQuestion_ReturnsAccurateResponse()
    {
        Assert.NotNull(_chatClient);

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "What is the capital of France?")
        };

        var response = await _chatClient.GetResponseAsync(messages);

        Assert.NotNull(response.Text);
        Assert.Contains("Paris", response.Text, StringComparison.OrdinalIgnoreCase);
    }

    [Fact]
    public async Task MultiTurn_MaintainsContext()
    {
        Assert.NotNull(_chatClient);

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "My name is Alice."),
        };

        var firstResponse = await _chatClient.GetResponseAsync(messages);
        messages.Add(new ChatMessage(ChatRole.Assistant, firstResponse.Text));
        messages.Add(new ChatMessage(ChatRole.User, "What is my name?"));

        var secondResponse = await _chatClient.GetResponseAsync(messages);

        Assert.NotNull(secondResponse.Text);
        Assert.Contains("Alice", secondResponse.Text, StringComparison.OrdinalIgnoreCase);
    }

    [Fact]
    public async Task QualityMetrics_MeetThresholds()
    {
        Assert.NotNull(_chatClient);

        var chatConfiguration = new ChatConfiguration(_chatClient);

        var scenarios = new List<EvaluationScenario>
        {
            new("greeting", "Simple greeting test",
                new List<ScenarioTurn> { new("user", "Hello, how are you?") },
                new List<EvaluationCriterion> { new("relevance", 3), new("coherence", 3) })
        };

        var results = await ScenarioRunner.RunScenariosAsync(
            _chatClient, chatConfiguration, scenarios);

        foreach (var result in results)
        {
            foreach (var metric in result.Metrics)
            {
                Assert.True(metric.Passed,
                    $"Scenario '{result.Name}' failed metric '{metric.Metric}' with score {metric.Score}");
            }
        }
    }
}

